                    .getY2ac_delta_q();
            int dcQValue = frame.getSegmentQuants().getSegQuants()[this.getSegmentId()].getY2dc();

            int[] input = new int[16];
            input[0] = sb.getTokens()[0] * dcQValue;

            for (int x = 1; x < 16; x++) {
                input[x] = sb.getTokens()[x] * acQValue;
