                break;
            case Globals.B_HE_PRED:
                // System.out.println("B_HE_PRED");

                int[] lp = new int[4];
                lp[0] = (al + 2 * left[0] + left[1] + 2) >> 2;
                lp[1] = (left[0] + 2 * left[1] + left[2] + 2) >> 2;
                lp[2] = (left[1] + 2 * left[2] + left[3] + 2) >> 2;
                lp[3] = (left[2] + 2 * left[3] + left[3] + 2) >> 2;

                for (int r = 0; r < 4; r++) {
                    for (int c = 0; c < 4; c++) {
                        p[c][r] = lp[r];
                    }
