                    }

                    if (left_available) {
                        for (int j = 0; j < 2; j++) {
                            SubBlock usb = leftMb.getUSubBlock(1, j);
                            SubBlock vsb = leftMb.getVSubBlock(1, j);
                            for (int i = 0; i < 4; i++) {
                                Uaverage += usb.getRecon()[3][i];
                                Vaverage += vsb.getRecon()[3][i];
                            }
                        }
                    }

                    int shift = 2;
                    if (up_available) {
                        shift++;
                    }
                    if (left_available) {
                        shift++;
