    public VP8Frame(final ImageInputStream stream, boolean debug) throws IOException {
        this.frame = stream;
        this.debug = debug;

        offset = frame.getStreamPosition();
        coefProbs = Globals.getDefaultCoefProbs();
        tokenBoolDecoders = new ArrayList<>();
