    private void createMacroBlockMetadata() {
        segmentIds = new int[macroBlockRows][macroBlockCols];
        filterLevels = new int[macroBlockRows][macroBlockCols];
        skipCoeffs = new int[macroBlockRows][macroBlockCols];
        yModes = new int[macroBlockRows][macroBlockCols];
        uvModes = new int[macroBlockRows][macroBlockCols];
        ySubBlockModes = new int[macroBlockRows][macroBlockCols][16];
    }

    private MacroBlock[] createMacroBlockRow(final int mbRow) {
        MacroBlock[] row = new MacroBlock[macroBlockCols + 2];

        for (int mbCol = 0; mbCol < macroBlockCols + 2; mbCol++) {
            row[mbCol] = new MacroBlock(mbCol, mbRow + 1, debug);
        }

        return row;
    }

    private void populateMacroBlock(final MacroBlock macroBlock, final int mbRow, final int mbCol) {
        macroBlock.setSegmentId(segmentIds[mbRow][mbCol]);
        macroBlock.setFilterLevel(filterLevels[mbRow][mbCol]);
        macroBlock.setSkipCoeff(skipCoeffs[mbRow][mbCol]);
        macroBlock.setYMode(yModes[mbRow][mbCol]);
        macroBlock.setUvMode(uvModes[mbRow][mbCol]);

        int[] modes = ySubBlockModes[mbRow][mbCol];
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                macroBlock.getYSubBlock(x, y).setMode(modes[y * 4 + x]);
            }
        }
    }

    private void initializeWindowedDecodeState() {
        createMacroBlockMetadata();
        topMacroBlockRow = createMacroBlockRow(-1);
        previousMacroBlockRow = topMacroBlockRow;
        currentMacroBlockRow = null;
        currentMacroBlockRowIndex = -1;
        lastNonBPredMacroBlockByColumn = new MacroBlock[macroBlockCols + 2];

        System.arraycopy(topMacroBlockRow, 0, lastNonBPredMacroBlockByColumn, 0, macroBlockCols + 2);
    }

    private static int ySubBlockModeIndex(final int subX, final int subY) {
        return subY * 4 + subX;
    }

    private int getYSubBlockMode(final int mbRow, final int mbCol, final int subX, final int subY) {
        if (mbRow < 0 || mbCol < 0 || mbRow >= macroBlockRows || mbCol >= macroBlockCols) {
            return 0;
        }

        return ySubBlockModes[mbRow][mbCol][ySubBlockModeIndex(subX, subY)];
    }

    private int getAboveYSubBlockMode(final int mbRow, final int mbCol, final int subX, final int subY) {
        if (subY > 0) {
            return getYSubBlockMode(mbRow, mbCol, subX, subY - 1);
        }

        return getYSubBlockMode(mbRow - 1, mbCol, subX, 3);
    }

    private int getLeftYSubBlockMode(final int mbRow, final int mbCol, final int subX, final int subY) {
        if (subX > 0) {
            return getYSubBlockMode(mbRow, mbCol, subX - 1, subY);
        }

        return getYSubBlockMode(mbRow, mbCol - 1, 3, subY);
    }

    public boolean decode(final WritableRaster raster, final ImageReadParam param) throws IOException {
        segmentQuants = new SegmentQuants();

        int c = frame.readUnsignedByte();
        frameType = getBitAsInt(c, 0);

        if (frameType != 0) {
            return false;
        }

        int versionNumber = getBitAsInt(c, 1) << 1;
        versionNumber += getBitAsInt(c, 2) << 1;
        versionNumber += getBitAsInt(c, 3);

//        logger.log("Version Number: " + versionNumber);
//        logger.log("show_frame: " + getBit(c, 4));

        int firstPartitionLengthInBytes;
        firstPartitionLengthInBytes = getBitAsInt(c, 5)/*<< 0*/;
        firstPartitionLengthInBytes += getBitAsInt(c, 6) << 1;
        firstPartitionLengthInBytes += getBitAsInt(c, 7) << 2;

        c = frame.readUnsignedByte();
        firstPartitionLengthInBytes += c << 3;

        c = frame.readUnsignedByte();
        firstPartitionLengthInBytes += c << 11;
//        logger.log("first_partition_length_in_bytes: "+ firstPartitionLengthInBytes);

        c = frame.readUnsignedByte();
//        logger.log("StartCode: " + c);

        c = frame.readUnsignedByte();
//        logger.log(" " + c);

        c = frame.readUnsignedByte();
//        logger.log(" " + c);

        c = frame.readUnsignedByte();
        int hBytes = c;
        c = frame.readUnsignedByte();
        hBytes += c << 8;
        width = (hBytes & 0x3fff);
//        logger.log("width: " + width);
//        logger.log("hScale: " + (hBytes >> 14));

        c = frame.readUnsignedByte();
        int vBytes = c;
        c = frame.readUnsignedByte();
        vBytes += c << 8;
        height = (vBytes & 0x3fff);
//        logger.log("height: " + height);
//        logger.log("vScale: " + (vBytes >> 14));
        int tWidth = width;
        int tHeight = height;
        if ((tWidth & 0xf) != 0) {
            tWidth += 16 - (tWidth & 0xf);
        }

        if ((tHeight & 0xf) != 0) {
            tHeight += 16 - (tHeight & 0xf);
        }
        macroBlockRows = tHeight >> 4;
        macroBlockCols = tWidth >> 4;
//        logger.log("macroBlockCols: " + macroBlockCols);
//        logger.log("macroBlockRows: " + macroBlockRows);

        initializeWindowedDecodeState();

        offset = frame.getStreamPosition();

        BoolDecoder bc = new BoolDecoder(frame, offset);

        if (frameType == 0) {
            int clr_type = bc.readBit();
//            logger.log("clr_type: " + clr_type);
//            logger.log("" + bc);

            int clamp_type = bc.readBit();
//            logger.log("clamp_type: " + clamp_type);

        }
        segmentationIsEnabled = bc.readBit();
//        logger.log("segmentation_enabled: " + segmentationIsEnabled);

        if (segmentationIsEnabled > 0) {
            // TODO: The original code logged a TODO warning here, but what is left to do?
            updateMacroBlockSegmentationMap = bc.readBit();
            updateMacroBlockSegmentatonData = bc.readBit();
//            logger.log("update_mb_segmentaton_map: " + updateMacroBlockSegmentationMap);
//            logger.log("update_mb_segmentaton_data: " + updateMacroBlockSegmentatonData);

            if (updateMacroBlockSegmentatonData > 0) {
                macroBlockSegementAbsoluteDelta = bc.readBit();
                /* For each segmentation feature (Quant and loop filter level) */
                for (int i = 0; i < Globals.MAX_MB_SEGMENTS; i++) {
                    int value = 0;
                    if (bc.readBit() > 0) {
                        value = bc.readLiteral(Globals.vp8MacroBlockFeatureDataBits[0]);
                        if (bc.readBit() > 0) {
                            value = -value;
                        }
                    }
                    this.segmentQuants.getSegQuants()[i].setQindex(value);
                }
                for (int i = 0; i < Globals.MAX_MB_SEGMENTS; i++) {
                    int value = 0;
                    if (bc.readBit() > 0) {
                        value = bc.readLiteral(Globals.vp8MacroBlockFeatureDataBits[1]);
                        if (bc.readBit() > 0) {
                            value = -value;
                        }
                    }
                    this.segmentQuants.getSegQuants()[i].setFilterStrength(value);
                }

                if (updateMacroBlockSegmentationMap > 0) {
                    macroBlockSegmentTreeProbs = new int[Globals.MB_FEATURE_TREE_PROBS];
